import{_ as s,C as c,o as h,c as t,a5 as e,j as p,E as l}from"./chunks/framework.a5no_H3L.js";const y=JSON.parse('{"title":"C# 与 .NET 的设计目标与运行链路","description":"C# 把源码编译为中间语言（IL），再由 .NET 运行时在目标平台上执行。理解 C# 要解决的问题和这条运行链路，是继续学习类型系统、对象语义和 .NET 运行时的共同起点。","frontmatter":{"type":"explanation","level":"basic"},"headers":[],"relativePath":"csharp/01-csharp-language/chapter-01-why-csharp.md","filePath":"csharp/01-csharp-language/chapter-01-why-csharp.md"}'),d={name:"csharp/01-csharp-language/chapter-01-why-csharp.md"},n={"data-src-line":"101","data-src-file":"csharp/01-csharp-language/chapter-01-why-csharp.md"};function i(o,a,g,u,m,f){const r=c("SvgDiagram");return h(),t("div",null,[a[0]||(a[0]=e(`<h1 id="c-与-net-的设计目标与运行链路" tabindex="-1" data-src-line="2" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">C# 与 .NET 的设计目标与运行链路 <a class="header-anchor" href="#c-与-net-的设计目标与运行链路" aria-label="Permalink to &quot;C# 与 .NET 的设计目标与运行链路&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">C# 把源码编译为中间语言（IL），再由 .NET 运行时在目标平台上执行。理解 C# 要解决的问题和这条运行链路，是继续学习类型系统、对象语义和 .NET 运行时的共同起点。</p><h2 id="_1-c-与-net-要解决什么问题" tabindex="-1" data-src-line="6" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">1. C# 与 .NET 要解决什么问题 <a class="header-anchor" href="#_1-c-与-net-要解决什么问题" aria-label="Permalink to &quot;1. C# 与 .NET 要解决什么问题&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">C# 诞生于 2000 年前后，.NET 平台的目标是解决 C/C++ 在大型应用开发中的两类难题：手动内存管理带来的正确性风险，以及程序难以跨平台运行。下面分别说明。</p><h3 id="_1-1-手动内存管理与类型安全" tabindex="-1" data-src-line="10" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">1.1 手动内存管理与类型安全 <a class="header-anchor" href="#_1-1-手动内存管理与类型安全" aria-label="Permalink to &quot;1.1 手动内存管理与类型安全&quot;">​</a></h3><p data-src-line="12" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">20 世纪 90 年代，C 和 C++ 广泛用于系统编程和桌面应用。它们提供接近硬件的控制能力，也把更多正确性责任交给开发者：</p><p data-src-line="14" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md"><strong>C 的问题：</strong> 开发者需要手动调用 <code>malloc()</code> 和 <code>free()</code>。遗漏释放会造成内存泄漏，重复释放会破坏堆状态，越界写入还可能覆盖其他对象的数据。这些问题可能在程序运行很久之后才暴露，排查成本很高。</p><p data-src-line="16" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md"><strong>C++ 的问题：</strong> 面向对象机制帮助组织复杂系统，但多重继承、模板错误信息和手动内存管理也增加了认知负担。开发者需要在表达能力、抽象层次和错误风险之间持续权衡。</p><p data-src-line="18" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">.NET 的设计方向是降低这些风险：由运行时承担内存回收，由编译器和类型系统提前发现更多错误，同时保留面向对象的表达能力。</p><h3 id="_1-2-跨平台与统一运行时" tabindex="-1" data-src-line="20" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">1.2 跨平台与统一运行时 <a class="header-anchor" href="#_1-2-跨平台与统一运行时" aria-label="Permalink to &quot;1.2 跨平台与统一运行时&quot;">​</a></h3><p data-src-line="22" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">C/C++ 程序通常需要针对目标平台编译，还要处理不同的系统调用、库和二进制格式。对于需要覆盖多种设备的软件，这会显著增加构建和维护成本。</p><p data-src-line="24" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">.NET 在源码和机器码之间加入 IL 和 CLR（Common Language Runtime），让同一份程序无需针对每个平台重新编译源码。<strong>一次编译，处处运行</strong>描述的正是这一设计方向：编译产物是平台无关的 IL，运行时由各平台上的 .NET 运行时提供。</p><h2 id="_2-net-的核心设计目标" tabindex="-1" data-src-line="26" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">2. .NET 的核心设计目标 <a class="header-anchor" href="#_2-net-的核心设计目标" aria-label="Permalink to &quot;2. .NET 的核心设计目标&quot;">​</a></h2><p data-src-line="28" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">C# 语言与 .NET 平台绑定在一起演进。语言设计围绕以下目标展开。</p><h3 id="_2-1-一次编译、跨平台运行" tabindex="-1" data-src-line="30" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">2.1 一次编译、跨平台运行 <a class="header-anchor" href="#_2-1-一次编译、跨平台运行" aria-label="Permalink to &quot;2.1 一次编译、跨平台运行&quot;">​</a></h3><p data-src-line="32" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">C# 源码先由编译器转换为 IL，再由目标平台上的 .NET 运行时执行。运行时屏蔽操作系统和 CPU 指令集的差异，让应用依赖统一的 IL 契约：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C/C++：Source → Machine Code → 针对目标平台运行</span></span>
<span class="line"><span>.NET：  Source → IL → .NET Runtime → 在安装对应运行时的平台上运行</span></span></code></pre></div><p data-src-line="39" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">IL 不是机器码，而是运行时可以进一步解释或编译的中间表示。.NET 支持多种语言（C#、F#、VB）编译到同一套 IL，这是「语言互操作」的基础。</p><h3 id="_2-2-自动内存管理" tabindex="-1" data-src-line="41" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">2.2 自动内存管理 <a class="header-anchor" href="#_2-2-自动内存管理" aria-label="Permalink to &quot;2.2 自动内存管理&quot;">​</a></h3><p data-src-line="43" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">.NET 不要求开发者手动释放托管对象内存。垃圾回收器（GC）识别不再可达的对象并回收其占用的托管堆空间。</p><p data-src-line="45" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">这减少了悬空指针、Use-After-Free 和 Double Free 等错误，但不会消除所有内存问题。可达性判断不等于业务使用判断：一个已经不再被业务访问的对象，只要仍被静态集合或缓存引用，GC 仍会视其为存活。非托管资源（文件句柄、网络连接、原生内存）不归 GC 管理，仍需要显式释放。</p><p data-src-line="47" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">GC 也有成本：它会消耗 CPU，并在部分阶段暂停应用线程。是否可接受取决于堆大小、分配速率、延迟目标和 GC 配置。</p><h3 id="_2-3-静态类型检查" tabindex="-1" data-src-line="49" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">2.3 静态类型检查 <a class="header-anchor" href="#_2-3-静态类型检查" aria-label="Permalink to &quot;2.3 静态类型检查&quot;">​</a></h3><p data-src-line="51" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">C# 是静态类型语言。变量类型在编译期确定，编译器会在运行前检查明显的类型错误。例如，<code>string s = 123;</code> 无法通过编译。</p><p data-src-line="53" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">类型检查不能发现所有运行时错误，例如空引用、数组越界和逻辑条件错误，但它把大量错误从生产环境提前到开发阶段。C# 8 起引入的可空引用类型进一步把「空引用」也纳入编译期检查，但这是可选启用的分析，不是强制的运行时保证。</p><h3 id="_2-4-类型安全与-il-验证" tabindex="-1" data-src-line="55" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">2.4 类型安全与 IL 验证 <a class="header-anchor" href="#_2-4-类型安全与-il-验证" aria-label="Permalink to &quot;2.4 类型安全与 IL 验证&quot;">​</a></h3><p data-src-line="57" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">.NET 运行时在执行 IL 前会进行验证，检查指令、类型和访问权限是否合法。这套机制用于降低非法 IL 直接破坏运行时的风险。</p><p data-src-line="59" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">IL 验证不是完整的安全沙箱。程序集加载、代码访问权限和操作系统权限分别约束不同层面的行为，不能互相替代。类型安全主要防止内存布局被破坏，而不是替代应用自身的鉴权逻辑。</p><h3 id="_2-5-面向对象与多范式" tabindex="-1" data-src-line="61" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">2.5 面向对象与多范式 <a class="header-anchor" href="#_2-5-面向对象与多范式" aria-label="Permalink to &quot;2.5 面向对象与多范式&quot;">​</a></h3><p data-src-line="63" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">C# 代码通常以类、接口、结构体、枚举和记录作为组织单位，通过封装、继承和多态表达对象之间的关系。</p><p data-src-line="65" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">面向对象不是唯一可用的编程方式。C# 也支持函数式风格：委托、Lambda、LINQ 和不可变记录；关键在于根据状态所有权和变化方向选择合适的抽象，而不是机械套用继承。</p><h3 id="_2-6-向后兼容" tabindex="-1" data-src-line="67" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">2.6 向后兼容 <a class="header-anchor" href="#_2-6-向后兼容" aria-label="Permalink to &quot;2.6 向后兼容&quot;">​</a></h3><p data-src-line="69" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">.NET 重视语言和 IL 层面的兼容性。旧版本编译生成的程序集通常能在较新运行时上运行，但源码能否重新编译、程序行为是否一致，还取决于使用的 API、第三方依赖和运行环境。因此 .NET 升级不能只看编译是否通过。</p><h2 id="_3-net-的性能取舍" tabindex="-1" data-src-line="71" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">3. .NET 的性能取舍 <a class="header-anchor" href="#_3-net-的性能取舍" aria-label="Permalink to &quot;3. .NET 的性能取舍&quot;">​</a></h2><p data-src-line="73" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">.NET 的设计目标不是在所有场景中追求极致性能，而是在性能、安全、可维护性和开发效率之间取得平衡。</p><p data-src-line="75" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">C/C++ 可以直接控制内存布局，并允许更接近硬件的优化，因此在部分系统编程场景中仍有优势。.NET 则通过垃圾回收、边界检查和运行时抽象承担更多自动化，也付出了相应开销。</p><p data-src-line="77" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">运行时提供两条执行路径：JIT 编译根据运行时 profile 优化长期运行的服务端程序；NativeAOT 则在发布时把 IL 预编译为原生代码，改善启动时间和内存占用，代价是失去部分动态特性。在充分预热、分配模式稳定的部分工作负载中，.NET 的吞吐量可以接近原生代码，但这不是保证；启动时间、短生命周期任务、尾延迟和特定数值计算仍可能更适合其他方案。</p><h2 id="_4-c-代码如何运行" tabindex="-1" data-src-line="79" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">4. C# 代码如何运行 <a class="header-anchor" href="#_4-c-代码如何运行" aria-label="Permalink to &quot;4. C# 代码如何运行&quot;">​</a></h2><p data-src-line="81" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">先用一个最小程序建立全局视角。使用 .NET SDK 创建控制台项目后，<code>Program.cs</code> 通常只有一行：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WriteLine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello, World!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p data-src-line="87" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">这是 C# 9 引入的顶级语句（top-level statements）：编译器会自动补全 <code>Program</code> 类和 <code>Main</code> 方法。在项目目录下执行：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet run</span></span></code></pre></div><p data-src-line="93" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md"><code>dotnet run</code> 会还原依赖、编译源码并启动运行时执行程序，输出：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, World!</span></span></code></pre></div><p data-src-line="99" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">这段代码从源码到 CPU 执行，主要经历以下步骤：<code>dotnet build</code> 把 C# 源码编译为 IL 并打包为程序集（<code>.dll</code>）；<code>dotnet run</code> 启动运行时加载程序集，由 JIT 把 IL 编译为机器码执行，或由 NativeAOT 直接运行预编译的原生代码。</p>`,45)),p("p",n,[l(r,{src:"/csharp/01-csharp-language-chapter-01-csharp-compile-pipeline.svg",alt:"C# 程序的执行流程：源码经 Roslyn 编译为 IL，运行时加载后由 JIT 或 NativeAOT 生成机器码"})]),a[1]||(a[1]=e('<p data-src-line="103" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">图中文字等价于以下流程：<code>Program.cs</code> 源码经 Roslyn 编译为 IL + 元数据（程序集 <code>.dll</code>），.NET 运行时加载并验证后，由 JIT 编译或 NativeAOT 预编译为机器码，最终由 CPU 执行。</p><p data-src-line="105" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">继续学习 C# 语言，进入<a href="./chapter-02-type-system.html">类型系统</a>和<a href="./chapter-03-object-values.html">对象与值语义</a>；理解程序如何运行，进入<a href="./../02-dotnet-runtime/chapter-01-compilation-clr.html">编译与 CLR</a>、<a href="./../02-dotnet-runtime/chapter-02-type-layout-memory.html">类型布局与内存</a>和 GC。</p><p data-src-line="107" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">这一章要记住的结论是：C# 源码先编译成平台无关的 IL，而不是目标 CPU 的机器码；运行时再由 .NET 运行时解释执行 IL，或把热点代码经 JIT 编译为本机机器码执行。</p><blockquote data-src-line="109" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md"><p data-src-line="109" data-src-file="csharp/01-csharp-language/chapter-01-why-csharp.md">本页的技术边界按 .NET 10 / C# 14 核对；顶级语句自 C# 9 引入，可空引用类型自 C# 8 引入，NativeAOT 自 .NET 7 起可用。官方参考：<a href="https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/" target="_blank" rel="noreferrer">C# 语言参考</a>、<a href="https://learn.microsoft.com/en-us/dotnet/" target="_blank" rel="noreferrer">.NET 文档</a>。</p></blockquote>',4))])}const _=s(d,[["render",i]]);export{y as __pageData,_ as default};
